import{z as o,x as i,o as B,c as d,q as s,j as l,D as A,d as E,s as n,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"WAL 的实现","description":"","frontmatter":{"title":"WAL 的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-wal-implementation.md","filePath":"cs/dbk-wal-implementation.md","lastUpdated":1791413859000}'),p={name:"cs/dbk-wal-implementation.md"};function c(f,a,h,C,D,u){const r=i("Mermaid");return B(),d("div",null,[a[2]||(a[2]=s('<h1 id="wal-的实现" tabindex="-1">WAL 的实现 <a class="header-anchor" href="#wal-的实现" aria-label="Permalink to &quot;WAL 的实现&quot;">​</a></h1><div class="epigraph"><p>提交不是把页写进盘，是把一条记录写进日志并等它落地；页什么时候上盘，是日志说了算。</p><footer>—— 据 Mohan, Haderle, Lindsay, Pirahesh and Schwarz, ARIES, ACM TODS 17(1), 1992；Gray and Reuter, *Transaction Processing*, 1993 整理</footer></div><p><a href="/cs/dbk-tx-manager">上一课</a>把提交序领了出来：可见性按它，冲突判定按它。缺口是最后的兑现——断电之后这个序还在不在。主干已立过 <a href="/cs/wal">WAL 规则</a>与 <a href="/cs/steal-noforce">steal/no-force</a>，<a href="/cs/aries-phases-clr">ARIES 三阶段</a>给过恢复算法；本课写日志机本身：记录怎么编、缓冲怎么攒、fsync 在哪几个点发生、检查点写什么。这也是本课程最后一个机制组件，收束课把全部组件接回一条写路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日志机的全部难点在一个不等式里：数据页可以随时、乱序、批量上盘（no-force 给了缓冲池自由，steal 允许脏页先走），唯一要守的是「页上盘之前，把它改出来的那些日志字节已经落盘」。实现就是把这个不等式变成两个可查的点：每页页头记 pageLSN（改出此页状态的最大日志序号），日志机对外报 flushedLSN（已落盘的最大序号）；缓冲池驱逐脏页前查一次 pageLSN \\(\\le\\) flushedLSN，不满足就先催日志落盘——第 1 课的驱逐路径在这里接上了钩子。漏查一次会错在哪：崩溃重启后，盘上是一个没有日志作证的新页态，REDO 无从谈起，UNDO 也找不到行——静默损坏，不是报错。</p><p><span class="marginnote">把不等式翻译成白话：「页 17 的状态改到第 500 号日志为止，那第 500 号日志必须已先落盘」。pageLSN 是页头上写的「我改到哪条日志」，flushedLSN 是日志机报的「日志已落到哪条」——前者不大于后者，页才许出门。</span></p><h3 id="记录与缓冲" tabindex="-1">记录与缓冲 <a class="header-anchor" href="#记录与缓冲" aria-label="Permalink to &quot;记录与缓冲&quot;">​</a></h3><p>记录是连续字节流上的一段：自己的 LSN、同一事务前一条记录的 LSN（prevLSN，UNDO 沿这条链回溯）、类型与载荷（物理到页还是逻辑到行的取舍，<a href="/cs/logging-granularity">日志粒度</a>讲过），块尾校验和防撕裂。日志缓冲是几兆到十几兆的内存尾段：追加只写内存，flushedLSN 只在 fsync 之后推进。提交是其中一类记录：事务管理器发来提交请求，日志机把它挂进队列攒批（<a href="/cs/group-commit">组提交</a>）——队列里所有等待者的记录一次 fsync 全部落盘，然后逐个应答。设备账很直白：NVMe 一次 fsync 约百微秒，一提交一 fsync 的上限是每秒万级；百笔合一，这笔成本摊薄百倍，代价是队头的事务多等一拍。</p><p><span class="marginnote">「提交先于应答」是持久性的兑现点：客户端收到提交应答时，那条 COMMIT 记录已经在盘上。要更低延迟就得改承诺——提交不等落盘、或只落半程，那是持久性等级（<a href="/cs/durability-levels">durability levels</a>）的生意，不是本课的默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查点是第三个 fsync 点。模糊检查点不停写入：先落一条 CKPT 记录（活跃事务表加脏页表），等它落盘，检查点即生效——REDO 的起点从日志开头前移到脏页表里最小的 recLSN。实现是后台线程周期性催刷脏页（仍守那个不等式）并补写 CKPT；检查点越勤，恢复分析越短，前台越多一次刷页开销——频率是 RTO 与吞吐的旋钮。恢复则是把不变量倒放：分析段从最后检查点起扫，重建活跃事务表与脏页表；REDO 段对脏页表里的页重复历史（不管事务是否提交，先刷到崩溃那一刻）；UNDO 段沿 prevLSN 链回滚未提交者，每回滚一条先写一条 CLR——恢复途中再崩溃，CLR 让重放幂等（<a href="/cs/aries-phases-clr">ARIES 三阶段与 CLR</a>已给算法，本课给它日志机的实现）。</p>',11)),(B(),l(t,null,{default:A(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXN%5B%22%E4%BA%8B%E5%8A%A1%EF%BC%9A%E6%94%B9%E9%A1%B5%E5%89%8D%22%5D%20--%3E%20APP%5B%22%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%E8%AE%B0%E5%BD%95%E5%88%B0%E7%BC%93%E5%86%B2%22%5D%0A%20%20APP%20--%3E%20MUT%5B%22%E6%94%B9%E9%A1%B5%EF%BC%8C%E9%A1%B5%E5%A4%B4%E8%AE%B0%20pageLSN%22%5D%0A%20%20TXN%20--%3E%20CREQ%5B%22%E6%8F%90%E4%BA%A4%E8%AF%B7%E6%B1%82%E5%85%A5%E9%98%9F%22%5D%0A%20%20CREQ%20--%3E%20GRP%5B%22%E7%BB%84%E6%8F%90%E4%BA%A4%EF%BC%9A%E4%B8%80%E6%89%B9%E4%B8%80%E6%AC%A1%20fsync%22%5D%0A%20%20GRP%20--%3E%20ACK%5B%22%E6%8E%A8%E8%BF%9B%20flushedLSN%EF%BC%8C%E9%80%90%E4%B8%AA%E5%BA%94%E7%AD%94%22%5D%0A%20%20MUT%20--%3E%20EVICT%7B%22%E7%BC%93%E5%86%B2%E6%B1%A0%E9%A9%B1%E9%80%90%E8%84%8F%E9%A1%B5%22%7D%0A%20%20EVICT%20--%3E%20CHK%7B%22pageLSN%20%E2%89%A4%20flushedLSN%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20FORCE%5B%22%E5%82%AC%E6%97%A5%E5%BF%97%E5%85%88%E8%90%BD%E7%9B%98%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20WR%5B%22%E9%A1%B5%E5%8F%AF%E4%B8%8A%E7%9B%98%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("这套机制扛得住乱序盘写，根子是「页的状态由一段日志定义」：盘上一页合法，当且仅当存在一段连续日志，重放它能精确得到这一页。pageLSN 与 flushedLSN 把「存在」变成可查的账，块校验和把「连续」变成可验的字节，CLR 把「重放可中断」变成结构性质。三个补丁各堵一类撕裂：日志块不满一个扇区的尾、页在半写时断电（doublewrite 或页校验和兜底，"),e("a",{href:"/cs/undo-redo-doublewrite"},"undo/redo 与 doublewrite"),E("讲过）、恢复中再崩溃。组提交看似优化，实则是把一次 fsync 从每事务成本摊成每队列成本；它的正确性边界在应答次序：先到的提交可以晚于后到的应答（各自等自己的记录落盘即可），但任何应答发出前，对应的 COMMIT 记录必须在 flushedLSN 之下——这个次序不能为省一次唤醒而松动。")],-1)),a[5]||(a[5]=e("p",null,"崩溃重启后，恢复的三段怎么倒放历史：",-1)),(B(),l(t,null,{default:A(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%EF%BC%9A%E9%87%8D%E5%90%AF%E5%BC%80%E5%A7%8B%E6%81%A2%E5%A4%8D%22%5D%20--%3E%20ANA%5B%22%E5%88%86%E6%9E%90%EF%BC%9A%E4%BB%8E%E6%9C%80%E5%90%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E6%89%AB%E6%97%A5%E5%BF%97%22%5D%0A%20%20ANA%20--%3E%20ATT%5B%22%E9%87%8D%E5%BB%BA%E6%B4%BB%E8%B7%83%E4%BA%8B%E5%8A%A1%E8%A1%A8%E4%B8%8E%E8%84%8F%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20ATT%20--%3E%20REDO%5B%22REDO%EF%BC%9A%E5%AF%B9%E8%84%8F%E9%A1%B5%E8%A1%A8%E9%87%8C%E7%9A%84%E9%A1%B5%E9%87%8D%E5%A4%8D%E5%8E%86%E5%8F%B2%22%5D%0A%20%20REDO%20--%3E%20UNDO%5B%22UNDO%EF%BC%9A%E6%B2%BF%20prevLSN%20%E9%93%BE%E5%9B%9E%E6%BB%9A%E6%9C%AA%E6%8F%90%E4%BA%A4%E8%80%85%22%5D%0A%20%20UNDO%20--%3E%20CLR%5B%22%E6%AF%8F%E5%9B%9E%E6%BB%9A%E4%B8%80%E6%9D%A1%E5%85%88%E5%86%99%E4%B8%80%E6%9D%A1%20CLR%22%5D%0A%20%20CLR%20--%3E%20DONE%5B%22%E5%86%8D%E5%B4%A9%E6%BA%83%E4%B9%9F%E8%83%BD%E5%B9%82%E7%AD%89%E9%87%8D%E6%94%BE%EF%BC%8C%E5%BA%93%E5%9B%9E%E5%88%B0%E4%B8%80%E8%87%B4%E7%82%B9%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">初学者容易以为「提交完成」意味着数据页已经写进盘。实际往往只有日志在盘上，数据页还躺在内存里等后台慢慢刷——这正是 no-force 的省法：崩溃也不怕，日志能把这页重放出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写单库日志机；复制与日志传送是另一条链路（主干有）。检查点的完整字段与 CLR 的格式，ARIES 原文与三阶段课已给，不重推。影子分页是不用日志机的另一条路，主干已对照，本课程不实现。组提交的批大小与等待时窗是调参：批越大吞吐越高、队头延迟越大，没有免费的窗口。</p><p><span class="marginnote">组提交的批大小像公交发车：班次越密（等待窗越短），乘客（事务）等得越少，但车越空（fsync 越频繁）；班次越疏，一趟拉满、单位成本越低，可队头那位等得最久。没有两全的窗口，只有按自己业务选的点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不等式只有一条：pageLSN \\(\\le\\) flushedLSN 才许页上盘，驱逐路径是它的检查点。</li><li>记录四要素：LSN、prevLSN 链、类型与载荷、块校验和；缓冲只写内存，fsync 后才推进序号。</li><li>提交应答先于落盘是越权；组提交把 fsync 摊给一批，不摊掉承诺。</li><li>模糊检查点前移 REDO 起点；CLR 让恢复自身可重入。</li><li>出处：Mohan et al., ARIES, TODS 1992；Gray and Reuter, 1993。</li></ul>',6))])}const S=o(p,[["render",c]]);export{N as __pageData,S as default};
